ruleBookInfo.init:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var dd = JSON.parse(result);
  var b = (dd && dd.meta) || dd || {};
  JSON.stringify({
    name: b.name || b.title || '',
    author: b.author || '',
    coverUrl: b.cover || '',
    intro: b.description || '',
    kind: '',
    tocUrl: ''
  });
})()

ruleToc.chapterList:
@js:
(function(){
  var out = [];
  try {
    var d = JSON.parse(result);
    var arr = d.chapters || [];
    for (var i=0;i<arr.length;i++){
      var it = arr[i] || {};
      var id = String(it.id || '');
      if (!id) continue;
      out.push({ name: it.title || '', url: id });
    }
  } catch(e) { out = []; }
  return out;
})()

ruleContent.content:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var d = JSON.parse(result);
  var u = (d && d.data && d.data.url) || '';
  u;
})()
